import{_ as t,o as r,c as s,ag as n}from"./chunks/framework.D5hoimZQ.js";const u=JSON.parse('{"title":"科学日报 · 2026-10-21（AI 系统架构）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/ai-system-architecture/science-daily-2026-10-21-ai.md","filePath":"topics/ai-system-architecture/science-daily-2026-10-21-ai.md"}'),e={name:"topics/ai-system-architecture/science-daily-2026-10-21-ai.md"};function g(i,o,a,l,c,d){return r(),s("div",null,[...o[0]||(o[0]=[n('<h1 id="科学日报-·-2026-10-21-ai-系统架构" tabindex="-1">科学日报 · 2026-10-21（AI 系统架构） <a class="header-anchor" href="#科学日报-·-2026-10-21-ai-系统架构" aria-label="Permalink to &quot;科学日报 · 2026-10-21（AI 系统架构）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-21.md</code> — 第40期 ｜ 🤖 AI 板块（5 篇 arXiv） 落盘说明：文件名带 <code>-ai</code> 后缀以<strong>避免与其它主题同名文件互引产生伪边</strong>（10-21 晨报第 2 条）。</p></blockquote><hr><h2 id="科学日报-2026-10-21-不用语言预训练也能做文生图——halcyon-用-1-275-算力反超" tabindex="-1">科学日报 2026-10-21：不用语言预训练也能做文生图——Halcyon 用 1/275 算力反超 <a class="header-anchor" href="#科学日报-2026-10-21-不用语言预训练也能做文生图——halcyon-用-1-275-算力反超" aria-label="Permalink to &quot;科学日报 2026-10-21：不用语言预训练也能做文生图——Halcyon 用 1/275 算力反超&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-21.md</code> ｜ arXiv: 2610.26863</p></blockquote><ul><li>反常识追问：现代文生图（T2I）系统<strong>都依赖互联网规模的语言预训练</strong>做文本条件生成——<strong>语言预训练对强 T2I 生成是否必要？</strong></li><li>方法：<strong>Halcyon</strong>——一族「<strong>早融合（early-fusion）</strong>」多模态自回归模型，<strong>完全从零</strong>在 <strong>1 亿图文对</strong>数据集 <strong>GPIC</strong> 上预训练。</li><li>数据： <ul><li>Halcyon-0.52B：以 <strong>18.2 分之一</strong>的预训练算力<strong>超过</strong> LlamaGen-XL/8（gFD <strong>48.0 vs 63.3</strong>）。</li><li>Halcyon-1.6B：以 <strong>275 分之一</strong>算力<strong>超过</strong> JiT-T2I-XXL/8++（gFD <strong>35.3 vs 41.0</strong>）。</li><li>对照实验：<strong>纯文本预训练并不能改善 T2I 生成</strong>；把 caption dropout 换成 I2T 监督，模型还顺带学会看图说话。</li></ul></li><li>结论：<strong>强 T2I 系统可以不靠互联网规模语言预训练、从零训练得到</strong>。</li><li>洞察（对本库 <code>ai-system-architecture</code>）：这条直接<strong>挑战「多模态 = 语言底座 + 视觉适配」的默认工程范式</strong>。与本库反复出现的元模式一致——<strong>「某个前置条件」常是历史路径依赖，而非能力必需</strong>：库内 10-08（把语言模型改装成按字节运行）同样是在问「这个前提真的必要吗？」。对人/组织的迁移：<strong>先分清「必需依赖」和「因为我们当年这么搭所以现在这样」，再决定要不要付那份预训练账单</strong>。</li></ul><hr><h2 id="科学日报-2026-10-21-openvlharness——给多模态模型装上「用工具」的推理外骨架" tabindex="-1">科学日报 2026-10-21：OpenVLHarness——给多模态模型装上「用工具」的推理外骨架 <a class="header-anchor" href="#科学日报-2026-10-21-openvlharness——给多模态模型装上「用工具」的推理外骨架" aria-label="Permalink to &quot;科学日报 2026-10-21：OpenVLHarness——给多模态模型装上「用工具」的推理外骨架&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-21.md</code> ｜ arXiv: 2610.26860</p></blockquote><ul><li>诊断：作者在 <strong>22 个基准</strong>上的对照研究显示，<strong>单纯增加基础模型的推理预算只带来有限提升</strong>——因为很多任务所需证据<strong>难以靠内部推理获得</strong>。</li><li>需求：这类任务需要<strong>有据可依的感知</strong>、<strong>外部知识</strong>和<strong>数值测量</strong>；且异构工具的输出必须<strong>可被模型理解</strong>、并<strong>跨推理步骤保留</strong>。</li><li>方法：<strong>OpenVLHarness</strong> = 「<strong>能力层 + 持久多模态记忆</strong>」： <ul><li><strong>能力层</strong>：任务级<strong>工具接口 + 证据渲染</strong>，把异构后端输出转成<strong>模型可读的观测</strong>。</li><li><strong>持久记忆</strong>：把图像、结构化数据、网页引用保留为<strong>可寻址工件</strong>。</li><li><strong>编码接口</strong>：对存储数据执行<strong>生成程序</strong>，从而<strong>组合多工具结果</strong> → 支持「获取 → 检查 → 组合」多模态证据的迭代。</li></ul></li><li>数据：22 个基准、8 个开源/闭源骨干，平均分比<strong>无工具基线高 9.7–12.6 分</strong>；GPT-6 Luna（中推理档）<strong>超过</strong> base/Codex/Visual Sketchpad 的最高档 <strong>7.7–8.5 分</strong>，而 token 成本<strong>最高仅为对手的 37%</strong>。</li><li>洞察（对本库 <code>ai-system-architecture</code> / harness 主题）：这是本库 <strong>harness ≈ 性能载体</strong> 主线的又一强证据（库内 09-21 编码 harness 三零件、10-19 MPT 自编排）。关键不是「模型更强」，而是<strong>把工具输出变成可寻址、可组合、可复用的证据</strong>——<strong>同样的模型，换个外骨架涨 10 分</strong>。与 <code>deepseek-harness-agent-runtime.md</code> 同构：<strong>能力层的设计正在变成与模型权重同等重要的变量</strong>。</li></ul><hr><h2 id="科学日报-2026-10-21-物理递归自我改进从哪来-llm-as-policy-的观测缩放律" tabindex="-1">科学日报 2026-10-21：物理递归自我改进从哪来？LLM-as-policy 的观测缩放律 <a class="header-anchor" href="#科学日报-2026-10-21-物理递归自我改进从哪来-llm-as-policy-的观测缩放律" aria-label="Permalink to &quot;科学日报 2026-10-21：物理递归自我改进从哪来？LLM-as-policy 的观测缩放律&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-21.md</code> ｜ arXiv: 2610.26848</p></blockquote><ul><li>问题：系统研究「<strong>物理递归自我改进（physical RSI）</strong>」的机制、缩放行为与泛化。</li><li>工具：<strong>PhysRSI-eval</strong>——用<strong>五轴指标</strong>量化物理 RSI：<strong>首次尝试表现 / 效率 / 成功率 / 预算 / 从失败中改进</strong>；在<strong>固定交互预算</strong>下于 <strong>18 个操作任务</strong>评测不同 VLM。</li><li>发现： <ul><li><strong>物理木桶假说</strong>：<strong>不同能力可能约束改进的不同环节</strong>（改进的速度取决于当前最短的那块板）。</li><li>五轴指标能<strong>区分公开基准均分接近的系统</strong>；<strong>高分未必意味着早期或高效的提升</strong>。</li><li><strong>观测缩放</strong>：既可从公开能力预测 VLM 智能体的相对表现，也可<strong>从早期物理反馈预判后续进展</strong>。</li><li><strong>工作区干预</strong>：去掉历史 → 后期成功率↓；<strong>冻结的工作区在未见布局上仍有用</strong>；三个跨任务案例<strong>更早成功</strong> → <strong>「场景内适配」与「可复用经验」可以并存</strong>。</li></ul></li><li>洞察（对本库 <code>ai-system-architecture</code> / <code>dream-rsi.md</code>）：本库 RSI 主线的新拼图——<strong>「自我改进」不是一个标量，而是五维的、且有瓶颈结构</strong>。特别是「<strong>冻结的工作区仍能迁移到新任务</strong>」这一条，对<strong>外脑自身</strong>极具参考：<strong>固化的历史沉淀（就算不再更新）在遇到新场景时仍有正向价值</strong>——这正是「知识网络复利」的实证版。与库内 <code>echo-gap-memory-reward-inflation.md</code>（自评分通道与被评内容解耦）互补：<strong>要度量改进，就得把&#39;卷面分&#39;拆成&#39;首次/效率/预算/失败后修复&#39;几路分别看</strong>。</li></ul><hr><h2 id="科学日报-2026-10-21-kronlstm——用克罗内克-δ-规则让长上下文线性注意力更稳" tabindex="-1">科学日报 2026-10-21：KronLSTM——用克罗内克 δ 规则让长上下文线性注意力更稳 <a class="header-anchor" href="#科学日报-2026-10-21-kronlstm——用克罗内克-δ-规则让长上下文线性注意力更稳" aria-label="Permalink to &quot;科学日报 2026-10-21：KronLSTM——用克罗内克 δ 规则让长上下文线性注意力更稳&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-21.md</code> ｜ arXiv: 2610.26834</p></blockquote><ul><li>问题：线性注意力把长上下文压进一个<strong>关联矩阵记忆</strong>，但「<strong>怎么更新记忆</strong>」直接决定<strong>稳定性与干扰</strong>。</li><li>方法：<strong>KronLSTM</strong>——基于「<strong>克罗内克 δ 规则（Kronecker Delta Rule）</strong>」的线性注意力架构，扩展 <strong>xLSTM</strong> 家族：加入<strong>记忆修正机制</strong>，在<strong>只沿矩阵空间单一方向</strong>修改记忆的同时<strong>修正目标关联</strong>。</li><li>为何有效：相比 δ 规则更新，这种「<strong>最小侵入式修正</strong>」<strong>减少与已存信息的干扰</strong>，因而特别适合<strong>长上下文建模</strong>。</li><li>理论保证：其记忆动力学可描述为一条<strong>收敛到稳态分布的马尔可夫链</strong>，且记忆矩阵的<strong>期望范数在整个输入序列上一致有界</strong>——因此<strong>无需额外归一化/稳定机制</strong>即可保证稳定。实验显示可与（门控）<strong>DeltaNet</strong> 家族抗衡，<strong>长上下文基准上尤其强</strong>。</li><li>洞察（对本库 <code>ai-system-architecture</code> / <code>llm-cache-pricing</code> 记忆主线）：与今日 MemT-1.0 同属「<strong>记忆是架构问题，不是外挂问题</strong>」。核心洞见是「<strong>修改要定向、要最小侵入</strong>」——<strong>改了目标条目，就尽量别动旁边没关系的条目</strong>。这在人类知识管理上同样成立：<strong>更新一条笔记时，理想做法是只动这一条 + 它的直接关联，而不是重写整个库</strong>（本库的增量落盘 + auto_link 正是这个思路）。</li></ul><hr><h2 id="科学日报-2026-10-21-memt-1-0——把「记忆」变成基础模型的内生能力" tabindex="-1">科学日报 2026-10-21：MemT-1.0——把「记忆」变成基础模型的内生能力 <a class="header-anchor" href="#科学日报-2026-10-21-memt-1-0——把「记忆」变成基础模型的内生能力" aria-label="Permalink to &quot;科学日报 2026-10-21：MemT-1.0——把「记忆」变成基础模型的内生能力&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-21.md</code> ｜ arXiv: 2610.26825</p></blockquote><ul><li>目标：<strong>记忆原生演化（memory-native evolution）</strong>——把记忆变成<strong>基础模型的内生能力</strong>，使其能<strong>持续积累并利用</strong>信息。</li><li>架构：<strong>MemT-1.0</strong> 把记忆<strong>内化为模型计算的一部分</strong>：在 <strong>Metis</strong> 之上采用 <strong>Gated DeltaNet-2</strong>，配以稳定的 <strong>token 级记忆更新</strong>机制；引入 <strong>Mixture-of-Storage</strong> 扩展原生记忆容量。</li><li>训练：背骨准备后，用<strong>持续预训练 + 后训练</strong>两阶段流程（<strong>34B tokens</strong> 训练数据 + 高效训练/推理基础设施），发布 <strong>MemT-1.0-Nano / -Flash</strong>。</li><li>结果：平均<strong>超过参数化记忆基线</strong>、与<strong>检索增强方法</strong>竞争力相当，同时<strong>基本保住通用能力</strong>；<strong>128K 历史长度</strong>下，MemT-1.0-Nano 相对<strong>全上下文 KV 缓存</strong>实现约 <strong>1.86× 端到端推理加速</strong>、<strong>持久存储减少 66×</strong>；通过<strong>内化检索到的程序性经验</strong>还提升了智能体任务成功率。</li><li>洞察（对本库 <code>ai-system-architecture</code> × <code>ai-brain</code>）：这是外脑的<strong>技术镜像</strong>——本库目前是「<strong>外挂式记忆</strong>」（markdown + 检索 + auto_link），MemT-1.0 走的是「<strong>内生式记忆</strong>」（记忆即计算）。两条路的取舍正是本库 <code>knowledge-system-arsenal.md</code> 关心的：<strong>外挂记忆可审计、可 git 化、可人工干预；内生记忆快、省存储、可端到端学习</strong>。值得记录：<strong>「程序性经验被内化后能提升任务成功率」</strong> 暗示——<strong>把&#39;怎么做&#39;沉淀下来（而非只存&#39;是什么&#39;）比单纯堆事实更值钱</strong>。</li></ul><hr><blockquote><p>📎 关联主题：<code>topics/ai-system-architecture/index.md</code> ｜ <code>topics/ai-brain/index.md</code> ｜ 第40期 AI 板块</p></blockquote><p>关键词：Halcyon、无需语言预训练、文生图、T2I、早融合、early-fusion、多模态自回归、GPIC、gFD、1/275算力、前置条件是不是历史路径依赖；OpenVLHarness、多模态工具使用、能力层、证据渲染、持久多模态记忆、可寻址工件、编码接口、token成本37%、harness即性能载体；physical RSI、PhysRSI-eval、五轴指标、物理木桶假说、观测缩放律、工作区干预、冻结工作区迁移、场景内适配与可复用经验；KronLSTM、克罗内克δ规则、线性注意力、关联矩阵记忆、记忆修正、最小侵入、马尔可夫链稳态、一致有界、免归一化、DeltaNet、xLSTM；MemT-1.0、记忆原生演化、memory-native、Gated DeltaNet-2、Mixture-of-Storage、128K、1.86倍加速、存储减少66倍、外挂记忆vs内生记忆、程序性经验内化</p><p>关联：<code>topics/ai-system-architecture/science-daily-2026-10-20.md</code>（Self-Building Labs / 行为耦合 / ORA / 抑制性消息传递 / ConSDL）、<code>topics/ai-system-architecture/dream-rsi.md</code>、<code>topics/ai-system-architecture/deepseek-harness-agent-runtime.md</code>、<code>topics/ai-system-architecture/echo-gap-memory-reward-inflation.md</code>、<code>topics/ai-system-architecture/llm-cache-pricing.md</code>、<code>topics/ai-brain/knowledge-system-arsenal.md</code>、<code>topics/ai-brain/auto-link-quality-fixes.md</code></p>',26)])])}const h=t(e,[["render",g]]);export{u as __pageData,h as default};
